/**
 * Generate compile-time parity assertions between the hand-written API types
 * in `src/lib/types/*.ts` and the generated OpenAPI schema (#165).
 *
 * Why this exists rather than just committing `schema.generated.ts`: a
 * generated file that nothing imports proves only that the file is fresh. It
 * does not prove the hand-written types the app actually uses still match the
 * backend — which is the thing project goal 2-7 asks for and the thing that
 * broke often enough to file this issue.
 *
 * Every hand-written type whose name matches a schema component gets an
 * assignability assertion, so `npm run type-check` fails when a Pydantic model
 * changes and its TypeScript mirror does not. The pairing is by name: adding a
 * new type named after a schema opts it in automatically, and there is no list
 * to forget to update.
 *
 * The assertion is one-directional — hand-written *extends* generated. That
 * catches a field the frontend declares that the backend no longer has, or
 * whose type changed. It deliberately permits the frontend omitting optional
 * fields it does not use, so a backend addition does not break the build
 * before anyone needs the new field.
 */

import { readFileSync, readdirSync, writeFileSync } from "node:fs"
import { dirname, join, resolve } from "node:path"
import { fileURLToPath } from "node:url"

const here = dirname(fileURLToPath(import.meta.url))
const uiRoot = resolve(here, "..")

const OPENAPI = join(uiRoot, "openapi.json")
const TYPES_DIR = join(uiRoot, "src", "lib", "types")
const OUT = join(uiRoot, "src", "lib", "api", "schema-parity.generated.ts")

const EXPORT_RE = /export (?:interface|type) (\w+)/g

const schemaNames = new Set(
  Object.keys(JSON.parse(readFileSync(OPENAPI, "utf8")).components.schemas),
)

/** module stem -> sorted type names that pair with a schema component */
const byModule = new Map()
for (const file of readdirSync(TYPES_DIR).sort()) {
  if (!file.endsWith(".ts") || file.endsWith(".test.ts")) continue
  const stem = file.replace(/\.ts$/, "")
  const source = readFileSync(join(TYPES_DIR, file), "utf8")
  const matched = []
  for (const m of source.matchAll(EXPORT_RE)) {
    if (schemaNames.has(m[1])) matched.push(m[1])
  }
  if (matched.length > 0) byModule.set(stem, matched.sort())
}

const lines = [
  "/**",
  " * GENERATED by ui/scripts/generate-schema-parity.mjs — do not edit.",
  " *",
  " * Compile-time parity between the hand-written API types and the OpenAPI",
  " * schema exported from the FastAPI app (#165). A failure here means a",
  " * Pydantic model and its TypeScript mirror have drifted: regenerate with",
  " * `make generate-types`, then reconcile the type the compiler names.",
  " *",
  " * Type-only. Emits no runtime code.",
  " */",
  "",
  'import type { components } from "@/lib/api/schema.generated"',
]

for (const [stem, names] of byModule) {
  lines.push(
    `import type {\n${names.map((n) => `  ${n},`).join("\n")}\n} from "@/lib/types/${stem}"`,
  )
}

lines.push(
  "",
  'type Schemas = components["schemas"]',
  "",
  "/** Fails to compile unless `T` is `true`. */",
  "type Assert<_T extends true> = never",
  "",
  "/** `true` when A is assignable to B. */",
  "type Extends<A, B> = A extends B ? true : false",
  "",
)

let count = 0
for (const [, names] of byModule) {
  for (const name of names) {
    lines.push(
      `export type Parity_${name} = Assert<Extends<${name}, Schemas["${name}"]>>`,
    )
    count += 1
  }
}

writeFileSync(OUT, lines.join("\n") + "\n", "utf8")
console.log(`wrote ${OUT} (${count} assertions)`)
